<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import InputError from '@/Components/InputError.vue';
import ValidationSummary from '@/Components/ValidationSummary.vue';
import { Head, useForm } from '@inertiajs/vue3';
import { ref } from 'vue';

const props = defineProps<{ coupons: any[]; discountTypes: string[] }>();
const editing = ref<any>(null);
const form = useForm({ code: '', description: '', discount_type: 'fixed', discount_value: '', is_active: true, starts_at: '', expires_at: '', usage_limit: '' });
const edit = (coupon: any) => { editing.value = coupon; form.defaults({ code: coupon.code, description: coupon.description || '', discount_type: coupon.discount_type, discount_value: coupon.discount_value, is_active: coupon.is_active, starts_at: coupon.starts_at || '', expires_at: coupon.expires_at || '', usage_limit: coupon.usage_limit || '' }); form.reset(); };
const cancel = () => { editing.value = null; form.defaults({ code: '', description: '', discount_type: 'fixed', discount_value: '', is_active: true, starts_at: '', expires_at: '', usage_limit: '' }); form.reset(); };
const submit = () => editing.value ? form.put(route('admin.coupons.update', editing.value.id), { onSuccess: cancel }) : form.post(route('admin.coupons.store'), { onSuccess: cancel });
</script>

<template>
    <Head title="Coupons" />
    <AuthenticatedLayout><template #header><h2 class="text-xl font-semibold">Coupons</h2></template><div class="mx-auto max-w-6xl space-y-5 p-6"><form @submit.prevent="submit" class="grid gap-3 bg-white p-5 shadow sm:grid-cols-3"><h3 class="sm:col-span-3 text-lg font-semibold">{{ editing ? 'Edit coupon' : 'Create coupon' }}</h3><div><label class="mb-1 block text-sm">Code</label><input v-model="form.code" required class="w-full rounded border-gray-300" /><InputError :message="form.errors.code" class="mt-1" /></div><div><label class="mb-1 block text-sm">Discount type</label><select v-model="form.discount_type" class="w-full rounded border-gray-300"><option v-for="type in discountTypes" :key="type" :value="type">{{ type }}</option></select></div><div><label class="mb-1 block text-sm">Discount value</label><input v-model="form.discount_value" type="number" min="0" step="0.01" required class="w-full rounded border-gray-300" /><InputError :message="form.errors.discount_value" class="mt-1" /></div><div><label class="mb-1 block text-sm">Description</label><input v-model="form.description" class="w-full rounded border-gray-300" /></div><div><label class="mb-1 block text-sm">Start date</label><input v-model="form.starts_at" type="date" class="w-full rounded border-gray-300" /></div><div><label class="mb-1 block text-sm">Expiration date</label><input v-model="form.expires_at" type="date" class="w-full rounded border-gray-300" /></div><div><label class="mb-1 block text-sm">Usage limit</label><input v-model="form.usage_limit" type="number" min="1" class="w-full rounded border-gray-300" /></div><label class="flex items-center gap-2 self-end"><input v-model="form.is_active" type="checkbox" /> Active</label><div class="flex items-end gap-3"><button class="rounded bg-indigo-600 px-3 py-2 text-white">{{ editing ? 'Save coupon' : 'Create coupon' }}</button><button v-if="editing" type="button" @click="cancel" class="text-gray-600">Cancel</button></div><div class="sm:col-span-3"><ValidationSummary :errors="form.errors" /></div></form><div class="overflow-x-auto bg-white shadow"><table class="min-w-full text-left text-sm"><thead class="bg-gray-50 text-gray-600"><tr><th class="p-3">Code</th><th class="p-3">Description</th><th class="p-3">Discount</th><th class="p-3">Validity</th><th class="p-3">Limit</th><th class="p-3">Status</th><th class="p-3"></th></tr></thead><tbody><tr v-for="coupon in coupons" :key="coupon.id" class="border-t"><td class="p-3 font-medium">{{ coupon.code }}</td><td class="p-3">{{ coupon.description || 'Not provided' }}</td><td class="p-3">{{ coupon.discount_type }}: {{ coupon.discount_value }}</td><td class="p-3">{{ coupon.starts_at || 'Any time' }} – {{ coupon.expires_at || 'No expiry' }}</td><td class="p-3">{{ coupon.usage_limit || 'Unlimited' }}</td><td class="p-3">{{ coupon.is_active ? 'Active' : 'Inactive' }}</td><td class="p-3"><button @click="edit(coupon)" class="text-indigo-600">Edit</button></td></tr></tbody></table><p v-if="!coupons.length" class="p-5 text-gray-600">No coupons have been created yet.</p></div></div></AuthenticatedLayout>
</template>
